"""Verifier: Sentinel training-set release (Northbeam Payments ML platform).

Visible tier: the release outputs under /app/out are compared exactly with the expected release, through
projection digests (one per modelling concept) and through per-record digests of the records that each trap
family and each decoy group touches. The per-record digests leave out the train-fitted fields (scaled features,
categorical indices, sample_weight, score); those are graded once, by the concept checks.

Hidden tier: the next release's exports are regenerated at grade time by the corpus generator whose readable
source is GENERATOR_SOURCES below (seeded with EVAL_SEED, integrity-checked against GENERATOR_SHA256). The
agent's /app/out/transform.py is run on them as a delta release on top of the agent's own visible outputs, as an
unprivileged user, in its own session, under a per-run time limit; its outputs are compared exactly. The same
builder is also run on a copy of those exports with one catalog file removed and must hold the release.
Expected values are stored only as SHA-256 digests.
"""

from __future__ import annotations

import base64
import fcntl
import hashlib
import json
import os
import shutil
import signal
import subprocess
import sys
import zlib
from pathlib import Path

from rewardkit import criteria, criterion

OUT = Path("/app/out")
APP_DATA = Path("/app/data")
SHARED = Path("/tmp/mlrel-verifier-cache")  # rewardkit may evaluate criteria in separate processes
EVAL_SEED = 9917353
RUN_UID = 65534
RUN_TIMEOUT = 1500  # seconds per builder run; the instruction promises the builder finishes one release in 25 minutes
GEN_TIMEOUT = 900  # seconds for regenerating the hidden exports
HELD_DROP_FILE = "chargebacks_vantage_2027-01.xml"  # catalog file removed from the hidden exports for the HELD run
EXAMPLE_KEYS = ["account_id", "categorical", "cluster_id", "event_ref", "event_time", "example_id", "features", "label",
                "label_source", "sample_weight", "score", "split"]
TRAIN_FITTED = ("features", "categorical", "sample_weight", "score")

REGION_GROUPS = ["central", "east", "north", "south", "west"]
SEGMENT_GROUPS = ["consumer", "corporate", "enterprise", "smb"]
SLICE_FILES = ["region_central.json", "region_east.json", "region_north.json", "region_south.json", "region_west.json",
               "segment_consumer.json", "segment_corporate.json", "segment_enterprise.json", "segment_smb.json"]
JSONL_FILES = ["normalized.jsonl"]
JSON_FILES = ["summary.json", "data_quality.json", "product_summary.json"] + SLICE_FILES

_CACHE: dict = {}


class _Lock:
    """Exclusive inter-process lock so each hidden-tier run happens once per grading run."""

    def __enter__(self):
        SHARED.mkdir(parents=True, exist_ok=True)
        self.fh = open(SHARED / ".lock", "w")
        fcntl.flock(self.fh, fcntl.LOCK_EX)
        return self

    def __exit__(self, *exc):
        fcntl.flock(self.fh, fcntl.LOCK_UN)
        self.fh.close()


# ------------------------------------------------------------------------------------- parsing and projections
def _sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _canon(obj) -> str:
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _read_jsonl(path: Path):
    rows = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.strip():
            rows.append(json.loads(line))
    return rows


def _load(root: Path):
    """Parse one output directory; None when anything is missing, malformed or hostile."""
    try:
        out = {}
        for name in JSONL_FILES:
            out[name] = _read_jsonl(root / name)
        for name in JSON_FILES:
            out[name] = json.loads((root / name).read_text(encoding="utf-8"))
        return out
    except Exception:  # noqa: BLE001 - any parse failure (including RecursionError) is a failed output, never a crash
        return None


def _examples(o):
    return [((r.get("split") if isinstance(r, dict) else None), r) for r in o["normalized.jsonl"]]


def _by_id(o):
    return sorted(_examples(o), key=lambda x: str(x[1].get("example_id") if isinstance(x[1], dict) else ""))


def _excl(o):
    dq = o["data_quality.json"]
    return dq.get("exclusions", []) if isinstance(dq, dict) else []


def _clusters(o):
    ps = o["product_summary.json"]
    return ps.get("clusters", []) if isinstance(ps, dict) else []


def _record_facts(r):
    """The per-record facts of one example: everything except the train-fitted fields."""
    return {k: v for k, v in r.items() if k not in TRAIN_FITTED} if isinstance(r, dict) else r


def _project(o, concept):
    ps, sm, dq = o["product_summary.json"], o["summary.json"], o["data_quality.json"]
    ex = _by_id(o)
    g = lambda r, k: r.get(k) if isinstance(r, dict) else None
    if concept == "pit":
        return [[g(r, "example_id"), g(g(r, "features") or {}, "merchant_cb_rate_bps"), g(g(r, "features") or {}, "ip_risk_score")]
                for _, r in ex] + [sm.get("imputed")]
    if concept == "labels":
        return [[g(r, "example_id"), g(r, "label"), g(r, "label_source")] for _, r in ex] + [
            sorted([e.get("file"), e.get("record_ref"), e.get("reason")] for e in _excl(o)
                   if isinstance(e, dict) and e.get("reason") in ("immature_label", "unresolved_label"))]
    if concept == "exclusions":
        return [_excl(o)]
    if concept == "manifest":
        return [dq.get("sources")]
    if concept == "splits":
        return [_clusters(o), [[s, g(r, "example_id"), g(r, "cluster_id")] for s, r in ex],
                [g(r, "example_id") for r in o["normalized.jsonl"]]]
    if concept == "preprocessing":
        return [ps.get("features"), [[g(r, "example_id"), g(r, "features")] for _, r in ex]]
    if concept == "class_weights":
        return [ps.get("class_weights"), [[g(r, "example_id"), g(r, "sample_weight")] for _, r in ex]]
    if concept == "vocab":
        return [ps.get("vocab"), [[g(r, "example_id"), g(r, "categorical")] for _, r in ex]]
    if concept == "scores_auc_psi":
        return [sm, [[g(r, "example_id"), g(r, "score")] for _, r in ex], ps.get("psi_edges"), ps.get("psi_train_props")]
    if concept == "slice_reports":
        return [o[n] for n in SLICE_FILES]
    raise KeyError(concept)


def _record_index(o):
    idx = {}
    for split, r in _examples(o):
        if isinstance(r, dict):
            idx[_sha(_canon(["ex", r.get("example_id")]))[:20]] = _sha(_canon([split, _record_facts(r)]))[:20]
    for e in _excl(o):
        if isinstance(e, dict):
            idx[_sha(_canon(["x", e.get("file"), e.get("record_ref")]))[:20]] = _sha(_canon(e.get("reason")))[:20]
    for c in _clusters(o):
        if isinstance(c, dict):
            idx[_sha(_canon(["cl", c.get("account_id")]))[:20]] = _sha(_canon([c.get("cluster_id"), c.get("split")]))[:20]
    return idx


def _row_key(r) -> str:
    return _sha(_canon(_record_facts(r)))[:20]


def _eval_digest(o, part):
    if part == "examples":
        return _sha(_canon([o["normalized.jsonl"], _clusters(o)]))
    if part == "state":
        return _sha(_canon([o["product_summary.json"], o["summary.json"], o["data_quality.json"]] + [o[n] for n in SLICE_FILES]))
    if part == "held":
        return _sha(_canon([o[n] for n in JSONL_FILES + JSON_FILES]))
    raise KeyError(part)


def _visible():
    if "visible" not in _CACHE:
        _CACHE["visible"] = _load(OUT)
    return _CACHE["visible"]


def _concept_ok(concept: str) -> bool:
    try:
        o = _visible()
        return o is not None and _sha(_canon(_project(o, concept))) == CONCEPT_DIGESTS[concept]
    except Exception:  # noqa: BLE001 - malformed output fails the check
        return False


def _slices():
    if "slices" not in _CACHE:
        _CACHE["slices"] = json.loads(zlib.decompress(base64.b64decode(SLICES)))
    return _CACHE["slices"]


def _slice_ok(name: str) -> bool:
    try:
        o = _visible()
        if o is None:
            return False
        if "index" not in _CACHE:
            _CACHE["index"] = _record_index(o)
        want = _slices().get(name)
        return bool(want) and all(_CACHE["index"].get(k) == v for k, v in want)
    except Exception:  # noqa: BLE001
        return False


# ------------------------------------------------------------------------------------- hidden tier: isolation helpers
def _readonly_tree(top: Path) -> None:
    """Root-owned and readable by the unprivileged runner, writable by nobody else."""
    for dirpath, _dirnames, filenames in os.walk(top):
        os.chmod(dirpath, 0o755)
        for f in filenames:
            p = os.path.join(dirpath, f)
            if os.path.isfile(p) and not os.path.islink(p):
                os.chmod(p, 0o644)


def _runner_dir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)
    if os.geteuid() == 0:
        os.chown(path, RUN_UID, RUN_UID)
    os.chmod(path, 0o700 if os.geteuid() == 0 else 0o755)


def _kill_runner_processes() -> None:
    """Kill every process of the unprivileged runner, including children that left the session."""
    if os.geteuid() != 0 or not Path("/proc").is_dir():
        return
    for p in Path("/proc").iterdir():
        if not p.name.isdigit():
            continue
        try:
            uid_line = next(ln for ln in (p / "status").read_text().splitlines() if ln.startswith("Uid:"))
            if int(uid_line.split()[1]) == RUN_UID:
                os.kill(int(p.name), signal.SIGKILL)
        except (OSError, StopIteration, ValueError, IndexError):
            continue


def _exec_builder(cmd, cwd: Path, env: dict) -> None:
    proc = subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                            cwd=str(cwd), env=env, start_new_session=True)
    try:
        proc.wait(timeout=RUN_TIMEOUT)
    finally:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except OSError:
            pass
        proc.wait()


# ------------------------------------------------------------------------------------- hidden tier: generation and runs
def _install_generator() -> Path:
    root = SHARED / "generator"
    shutil.rmtree(root, ignore_errors=True)
    root.mkdir(parents=True)
    digest = hashlib.sha256()
    for name in sorted(GENERATOR_SOURCES):
        src = GENERATOR_SOURCES[name]
        digest.update(name.encode("utf-8") + b"\0" + src.encode("utf-8") + b"\0")
        (root / name).write_text(src, encoding="utf-8")
    if digest.hexdigest() != GENERATOR_SHA256:
        raise ValueError("generator sources do not match GENERATOR_SHA256")
    _readonly_tree(root)
    return root


def _regenerate() -> Path | None:
    if "eval_data" not in _CACHE:
        with _Lock():
            _CACHE["eval_data"] = _regenerate_locked()
    return _CACHE["eval_data"]


def _regenerate_locked() -> Path | None:
    target = SHARED / "eval" / "release_drop"
    if (SHARED / "eval" / "DONE").is_file():
        return target
    if (SHARED / "eval" / "FAILED").is_file():
        return None
    data = None
    try:
        gen = _install_generator()
        shutil.rmtree(target.parent, ignore_errors=True)
        target.parent.mkdir(parents=True)
        code = ("import sys; sys.dont_write_bytecode = True; sys.path.insert(0, sys.argv[1]); import build_corpus; "
                "build_corpus.build('P2', __import__('pathlib').Path(sys.argv[2]), seed=int(sys.argv[3]), quiet=True)")
        done = subprocess.run([sys.executable, "-c", code, str(gen), str(target), str(EVAL_SEED)], capture_output=True,
                              text=True, timeout=GEN_TIMEOUT)
        if done.returncode == 0:
            _readonly_tree(target.parent)
            data = target
    except Exception:  # noqa: BLE001 - a generation failure fails the hidden checks, never the run
        data = None
    (SHARED / "eval" / ("DONE" if data is not None else "FAILED")).write_text("", encoding="utf-8")
    return data


def _variant(label: str, data: Path, drop: str | None = None) -> Path | None:
    """A read-only copy of the hidden exports at another path, optionally without one file."""
    try:
        top = SHARED / label
        target = top / "inbox" / "TR_next_exports"
        with _Lock():
            if not (top / "DONE").is_file():
                shutil.rmtree(top, ignore_errors=True)
                shutil.copytree(data, target, ignore=(lambda d, names: [n for n in names if n == drop]) if drop else None)
                _readonly_tree(top)
                (top / "DONE").write_text("", encoding="utf-8")
        return target
    except Exception:  # noqa: BLE001
        return None


def _run(label: str, data: Path, poison_app_data: bool = False):
    """Run the delivered transform on `data` as an unprivileged user; returns parsed outputs or None."""
    key = ("run", label)
    if key not in _CACHE:
        with _Lock():
            _CACHE[key] = _run_locked(label, data, poison_app_data)
    return _CACHE[key]


def _run_locked(label: str, data: Path, poison_app_data: bool):
    work = SHARED / f"run-{label}"
    out = work / "release_out"
    if (work / "DONE").is_file():
        return _finish(out)
    if (work / "FAILED").is_file():
        return None
    result = None
    script = OUT / "transform.py"
    planted = False
    try:
        if not script.is_file() or _visible() is None:
            raise FileNotFoundError(script)
        shutil.rmtree(work, ignore_errors=True)
        work.mkdir(parents=True)
        prior = work / "prior_release"
        shutil.copytree(OUT, prior)
        shutil.copy2(script, work / "transform.py")
        _readonly_tree(work)
        home = work / "home"
        _runner_dir(out)
        _runner_dir(home)
        if poison_app_data and not APP_DATA.exists():
            shutil.copytree(data, APP_DATA)
            planted = True
            reg = APP_DATA / "source_register.md"
            reg.write_text(reg.read_text(encoding="utf-8").replace("| ", "|x ", 40), encoding="utf-8")
            _readonly_tree(APP_DATA)
        cmd = [sys.executable, str(work / "transform.py"), str(data), str(out), "--prior", str(prior)]
        if shutil.which("setpriv") and os.geteuid() == 0:
            cmd = ["setpriv", f"--reuid={RUN_UID}", f"--regid={RUN_UID}", "--clear-groups"] + cmd
        _exec_builder(cmd, home, {"PATH": "/usr/local/bin:/usr/bin:/bin", "HOME": str(home)})
        result = _finish(out)
    except Exception:  # noqa: BLE001 - a crashed, hung or hostile builder yields no outputs
        result = None
    finally:
        _kill_runner_processes()
        if planted:
            shutil.rmtree(APP_DATA, ignore_errors=True)
    try:
        if work.is_dir():
            (work / ("DONE" if result is not None else "FAILED")).write_text("", encoding="utf-8")
    except OSError:
        pass
    return result


def _finish(out: Path):
    result = _load(out)
    if result is not None:
        try:
            result["_bytes"] = {n: (out / n).read_bytes() for n in JSONL_FILES + JSON_FILES}
        except OSError:
            return None
    return result


def _eval_primary():
    data = _regenerate()
    return None if data is None else _run("primary", data)


def _eval_ok(part: str) -> bool:
    try:
        o = _eval_primary()
        return o is not None and _eval_digest(o, part) == EVAL_DIGESTS[part]
    except Exception:  # noqa: BLE001
        return False


def _deterministic_primary():
    """Primary hidden outputs, but only when a same-condition repeat run produced identical bytes."""
    data = _regenerate()
    a = _eval_primary()
    if data is None or a is None:
        return None, None
    rep = _run("repeat", data)
    if rep is None or rep["_bytes"] != a["_bytes"]:
        return None, None  # nondeterminism is priced once, by negative_nondeterministic_output
    return data, a


# ------------------------------------------------------------------------------------- checks
@criterion(description="all fourteen release outputs exist under /app/out with the documented file shapes")
def outputs_have_documented_shape(workspace: Path) -> bool:
    try:
        o = _visible()
        if o is None or not (OUT / "transform.py").is_file():
            return False
        docs = [o[n] for n in JSON_FILES]
        if not all(isinstance(x, dict) for x in docs):
            return False
        status = docs[0].get("status")
        if status not in ("PUBLISHED", "HELD") or any(x.get("status") != status for x in docs):
            return False
        if not isinstance(o["data_quality.json"].get("sources"), list):
            return False
        return all(isinstance(r, dict) and sorted(r) == EXAMPLE_KEYS for _, r in _examples(o))
    except Exception:  # noqa: BLE001
        return False


