@criterion(description="the delivered transform holds the hidden release when one catalog file is missing")
def held_release_when_catalog_file_missing(workspace: Path) -> bool:
    try:
        data = _regenerate()
        variant = None if data is None else _variant("held", data, drop=HELD_DROP_FILE)
        o = None if variant is None else _run("held", variant)
        return o is not None and _eval_digest(o, "held") == EVAL_DIGESTS["held"]
    except Exception:  # noqa: BLE001
        return False


@criterion(description="the delivered transform replays this release's answers on the next release's exports")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # Inverted polarity: returns True only on positive evidence that the builder replays this release; the
    # negative weight does the punishing. A crash, a timeout or a wrong-but-original hidden run is incomplete
    # work, graded by the eval_* checks, never read as hardcoding. Rows are compared on their per-record facts.
    try:
        vis = _visible()
        if vis is None or _regenerate() is None:
            return False
        o = _eval_primary()
        if o is None:
            return False
        release = vis["summary.json"].get("release_id") if isinstance(vis["summary.json"], dict) else None
        hidden = o["summary.json"].get("release_id") if isinstance(o["summary.json"], dict) else None
        if release and hidden == release:
            return True
        seen = {_row_key(r) for r in vis["normalized.jsonl"]}
        rows = o["normalized.jsonl"]
        return bool(rows) and 2 * sum(1 for r in rows if _row_key(r) in seen) > len(rows)
    except Exception:  # noqa: BLE001
        return False


@criterion(description="the transform output depends on the directory path of its inputs")
def negative_filename_dependent_behaviour(workspace: Path) -> bool:
    # Inverted polarity: returns True when a deterministic builder writes different bytes for the same exports
    # placed at another path; the negative weight does the punishing.
    try:
        data, a = _deterministic_primary()
        if a is None:
            return False
        moved = _variant("moved", data)
        b = None if moved is None else _run("moved", moved)
        return b is not None and b["_bytes"] != a["_bytes"]
    except Exception:  # noqa: BLE001
        return False


@criterion(description="the transform reads /app/data instead of the input directory it is given")
def negative_reads_training_corpus_at_runtime(workspace: Path) -> bool:
    # Inverted polarity: returns True when a deterministic builder changes its output once a poisoned copy of the
    # exports sits at /app/data; the negative weight does the punishing.
    try:
        if APP_DATA.exists():
            return False
        data, a = _deterministic_primary()
        if a is None:
            return False
        c = _run("poisoned", data, poison_app_data=True)
        return c is not None and c["_bytes"] != a["_bytes"]
    except Exception:  # noqa: BLE001
        return False


@criterion(description="two runs of the transform on the same inputs produce different bytes")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # Inverted polarity: returns True when two identical runs disagree; the negative weight does the punishing.
    try:
        data = _regenerate()
        a = _eval_primary()
        if data is None or a is None:
            return False
        b = _run("repeat", data)
        return b is not None and b["_bytes"] != a["_bytes"]
    except Exception:  # noqa: BLE001
        return False


