    tok = dict(m0=m[0], m1=m[1], m2=m[2], m3=m[3], m4=m[4], m5=m[5], rel=rel, prev=p["prev"])
    return {slot: tmpl.format(**tok) for slot, tmpl, *_ in INVENTORY}

